import { motion } from "framer-motion";

export default function ContactPage() {
  return (
    <motion.div 
      id="contact"
      className="relative w-full min-h-screen flex flex-col items-center justify-center bg-white text-black px-4 md:px-10 py-10"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 1 }}
    >
      {/* Tło */}
      <div 
        className="absolute inset-0 bg-cover bg-center" 
        style={{ backgroundImage: "url('https://images.unsplash.com/photo-1430417934865-589b63ad5c00?q=80&w=2076&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D')" }}
      ></div>
      <div className="absolute inset-0 bg-black bg-opacity-50"></div>
      
      {/* Treść kontaktu */}
      <div className="relative max-w-2xl text-left text-white px-4 md:px-8">
        <motion.h1 
          className="text-3xl sm:text-4xl md:text-6xl font-bold mb-6 md:mb-8"
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
        >
          Kontakt</motion.h1>

        <div className='mb-6 md:mb-12'></div>

        <motion.p 
          className="text-base sm:text-lg md:text-2xl font-semibold mb-3 md:mb-4"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8, delay: 0.2 }}
        >
          Numer telefonu: <span className="font-normal">123-456-7890</span>
        </motion.p>

        <motion.p 
          className="text-base sm:text-lg md:text-2xl font-semibold mb-3 md:mb-4"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8, delay: 0.4 }}
        >
          Adres: <span className="font-normal">123 Dowolna Ulica, Dowolne Miasto, ST 12345</span>
        </motion.p>

        <motion.p 
          className="text-base sm:text-lg md:text-2xl font-semibold mb-3 md:mb-4"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8, delay: 0.6 }}
        >
          Strona internetowa: 
          <a href="#" className="text-white font-normal hover:text-gray-400 transition duration-300"> www.przykladowastrona.com</a>
        </motion.p>

        <motion.p 
          className="text-base sm:text-lg md:text-2xl font-semibold mb-6 md:mb-6"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8, delay: 0.8 }}
        >
          Adres e-mail: 
          <a href="mailto:kontakt@przykladowastrona.com" className="text-white font-normal hover:text-gray-400 transition duration-300"> kontakt@przykladowastrona.com</a>
        </motion.p>

        <motion.p 
          className="text-lg sm:text-xl md:text-3xl font-semibold italic"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 1 }}
        >
          <div className='mt-6 md:mt-12'></div>
          "Razem budujemy przyszłość!"
        </motion.p>
      </div>
    </motion.div>
  );
}
