import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { Pie } from "react-chartjs-2";
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from "chart.js";
import ChartDataLabels from "chartjs-plugin-datalabels";

ChartJS.register(ArcElement, Tooltip, Legend, ChartDataLabels);

export default function PieChartPage() {
  const [data] = useState({
    labels: [
      "Samotne osoby pracujące",
      "Rodziny z małymi dziećmi",
      "Rodziny ze starszymi dziećmi",
      "Pary",
      "Seniorzy"
    ],
    datasets: [
      {
        data: [36.1, 30.1, 12, 12, 9.6],
        backgroundColor: [
          "#F5F5F5", "#D9D9D9", "#BFBFBF", "#8C8C8C", "#3C3C3C"
        ],
        borderWidth: 1,
        cutout: "40%"
      }
    ]
  });

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    animation: {
      animateRotate: true,
      animateScale: true,
      duration: 1500,
      easing: "easeOutQuad"
    },
    plugins: {
      legend: {
        display: false
      },
      tooltip: {
        enabled: true
      },
      datalabels: {
        color: "#000",
        font: {
          size: 14,
          weight: "bold"
        },
        anchor: "center",
        align: "center",
        formatter: (value) => `${value}%`
      }
    }
  };

  return (
    <motion.div 
      id="market-gap"
      className="w-full min-h-screen flex flex-col items-center justify-start bg-white py-8 px-4 md:px-12 lg:px-20"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 1 }}
    >
      <motion.div 
        className="w-full flex flex-col md:flex-row justify-between items-center py-6 text-center md:text-left space-y-6 md:space-y-0"
        initial={{ opacity: 0, y: -50 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1, delay: 0.3 }}
      >
        {/* Nagłówek i opis */}
        <div className="md:w-1/2">
          <h1 className="text-2xl md:text-4xl font-bold text-gray-800">Luka na rynku</h1>
          <p className="text-base md:text-lg lg:text-xl text-gray-600 mt-4">
            Współcześni pracownicy oraz młode rodziny poszukują mieszkań dostosowanych do ich stylu życia, ale rynek nie zawsze spełnia ich potrzeby.
          </p>
        </div>
      </motion.div>

      {/* Wykres + etykiety */}
      <motion.div 
        className="flex flex-col md:flex-row items-center justify-center mt-8 w-full max-w-[1100px] gap-12"
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 1, delay: 0.5, ease: [0.34, 1.56, 0.64, 1] }}
      >
        {/* Wykres */}
        <div className="w-full max-w-[300px] sm:max-w-[400px] md:max-w-[450px] lg:max-w-[500px] h-[300px] sm:h-[400px] md:h-[450px] lg:h-[500px] flex items-center justify-center">
          <motion.div
            className="w-full h-full"
            initial={{ scale: 0.5, rotate: 180 }}
            animate={{ scale: 1, rotate: 0 }}
            transition={{ duration: 1.5, ease: [0.34, 1.56, 0.64, 1] }}
          >
            <Pie data={data} options={options} />
          </motion.div>
        </div>

        {/* Lista etykiet */}
        <motion.div 
          className="flex flex-col space-y-4 text-left text-sm sm:text-base md:text-lg text-gray-700"
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 1, delay: 0.7 }}
        >
          {data.labels.map((label, index) => (
            <div key={index} className="flex items-center">
              <span 
                className="w-4 h-4 sm:w-5 sm:h-5 rounded-full mr-3 border border-gray-400" 
                style={{ backgroundColor: data.datasets[0].backgroundColor[index] }}
              ></span>
              <p className="font-medium">{label} - {data.datasets[0].data[index]}%</p>
            </div>
          ))}
        </motion.div>
      </motion.div>
    </motion.div>
  );
}
