import { motion } from "framer-motion";
import { useState } from "react";

export default function Header() {
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <motion.header
      className="fixed top-0 left-0 w-full bg-black bg-opacity-80 backdrop-blur-md shadow-lg z-50"
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.8 }}
    >
      <div className="max-w-7xl mx-auto px-6 md:px-12 py-4 flex justify-between items-center">
        {/* LOGO */}
        <motion.h1
          className="text-2xl md:text-4xl font-bold text-white"
          initial={{ opacity: 0, x: -30 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8 }}
        >
          RealEstate
        </motion.h1>

        {/* MENU - Desktop */}
        <nav className="hidden md:flex space-x-8 text-lg text-white">
          <a href="#home" className="hover:text-gray-300 transition duration-300">Strona Główna</a>
          <a href="#market-gap" className="hover:text-gray-300 transition duration-300">Luka na Rynku</a>
          <a href="#projects" className="hover:text-gray-300 transition duration-300">Projekty</a>
          <a href="#roadmap" className="hover:text-gray-300 transition duration-300">Plan Działania</a>
          <a href="#contact" className="hover:text-gray-300 transition duration-300">Kontakt</a>
        </nav>

        {/* MENU - Mobile Toggle */}
        <button
          className="md:hidden text-white text-3xl focus:outline-none"
          onClick={() => setMenuOpen(!menuOpen)}
        >
          ☰
        </button>
      </div>

      {/* MENU - Mobile */}
      {menuOpen && (
        <motion.nav
          className="md:hidden flex flex-col items-center bg-black bg-opacity-90 text-white space-y-6 py-6"
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
        >
          <a href="#home" className="hover:text-gray-300 transition duration-300" onClick={() => setMenuOpen(false)}>Strona Główna</a>
          <a href="#market-gap" className="hover:text-gray-300 transition duration-300" onClick={() => setMenuOpen(false)}>Luka na Rynku</a>
          <a href="#projects" className="hover:text-gray-300 transition duration-300" onClick={() => setMenuOpen(false)}>Projekty</a>
          <a href="#roadmap" className="hover:text-gray-300 transition duration-300" onClick={() => setMenuOpen(false)}>Plan Działania</a>
          <a href="#contact" className="hover:text-gray-300 transition duration-300" onClick={() => setMenuOpen(false)}>Kontakt</a>
        </motion.nav>
      )}
    </motion.header>
  );
}
