import { motion } from "framer-motion";
import Chart from '../icons/chart.png';
import Community from '../icons/community.png';
import Handshake from '../icons/handshake.png';

export default function WhatItCouldMean() {
  return (
    <motion.div 
      className="w-full min-h-[60vh] flex flex-col bg-gray-100 p-6 md:p-10"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 1 }}
    >
      <motion.h1 
        className="text-3xl md:text-5xl font-bold text-gray-700 mb-10 md:mb-16 text-left max-w-7xl mx-auto"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1, delay: 0.3 }}
      >
        Co to może oznaczać?
      </motion.h1>
      
      <motion.div 
        className="flex flex-col md:flex-row justify-center items-center gap-10 md:gap-20 w-full max-w-7xl mx-auto mt-8"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 1, delay: 0.5 }}
      >
        {/* Ikona 1 */}
        <motion.div 
          className="flex flex-col items-center text-center gap-6"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 0.6 }}
        >
          <img src={Chart} alt="Wykres" className="w-24 md:w-32 h-24 md:h-32 mb-4 md:mb-6" />
          <p className="text-lg md:text-xl text-gray-600">Zwiększenie sprzedaży i rozwój rynku nieruchomości</p>
        </motion.div>
        
        {/* Ikona 2 */}
        <motion.div 
          className="flex flex-col items-center text-center gap-6"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 0.7 }}
        >
          <img src={Community} alt="Społeczność" className="w-24 md:w-32 h-24 md:h-32 mb-4 md:mb-6" />
          <p className="text-lg md:text-xl text-gray-600">Nowe miejsce do życia dla mieszkańców i przedsiębiorców</p>
        </motion.div>
        
        {/* Ikona 3 */}
        <motion.div 
          className="flex flex-col items-center text-center gap-6"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 0.8 }}
        >
          <img src={Handshake} alt="Uścisk dłoni" className="w-24 md:w-32 h-24 md:h-32 mb-4 md:mb-6" />
          <p className="text-lg md:text-xl text-gray-600">Dynamicznie rozwijająca się społeczność dla każdego</p>
        </motion.div>
      </motion.div>
    </motion.div>
  );
}
