import { motion } from "framer-motion";

export default function CommercialDevelopment() {
  return (
    <motion.div 
      className="w-screen h-screen relative flex items-center justify-center px-4 md:px-12 lg:px-20"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 1 }}
    >
      {/* Tło */}
      <div 
        className="absolute inset-0 bg-cover bg-center" 
        style={{ backgroundImage: "url('https://images.unsplash.com/photo-1542883339-f2680a3e3996?q=80&w=1974&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D')" }}
      ></div>
      <div className="absolute inset-0 bg-black bg-opacity-40"></div>
      
      {/* Nagłówek */}
      <motion.div 
        className="absolute top-10 left-5 md:left-10 p-4 md:p-6 text-white text-left"
        initial={{ opacity: 0, x: -50 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 1, delay: 0.3 }}
      >
        <h1 className="text-3xl md:text-5xl font-bold">Nowoczesne Centra Handlowe</h1>
      </motion.div>
      
      {/* Opis */}
      <motion.div 
        className="absolute right-5 bottom-10 md:right-10 md:bottom-20 p-6 md:p-10 text-white text-right w-full md:w-2/3 lg:w-1/3 bg-black bg-opacity-50 flex items-center justify-center"
        initial={{ opacity: 0, y: 50 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1, delay: 0.5 }}
      >
        <p className="text-lg md:text-2xl font-bold leading-snug">
          Tworzymy przestrzenie handlowe przyszłości. Nowoczesne centra usługowe zapewniają 
          komfortowe zakupy, dostępność dla każdego i przyjazne środowisko dla biznesu. 
          Ożywiamy miejskie przestrzenie i wspieramy lokalne społeczności.
        </p>
      </motion.div>
    </motion.div>
  );
}
