import { motion } from "framer-motion";

export default function CostEstimate() {
  return (
    <motion.div 
      className="w-full min-h-screen flex flex-col items-start justify-start bg-black text-white px-4 md:px-10 py-10"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 1 }}
    >
      <h1 className="text-3xl md:text-5xl font-bold mb-10 md:mb-16 text-left">Szacowany Koszt</h1>
      <div className="w-full flex justify-center items-center flex-grow">
        <div className="w-full max-w-3xl border-2 border-white overflow-hidden shadow-lg">
          <table className="w-full text-sm md:text-lg lg:text-2xl border-collapse">
            <thead>
              <tr className="bg-white text-black">
                <th className="p-4 md:p-6 text-left border-2 border-white">Usługa</th>
                <th className="p-4 md:p-6 text-right border-2 border-white">Koszt</th>
              </tr>
            </thead>
            <tbody>
              <tr className="bg-black text-white border-2 border-white">
                <td className="p-4 md:p-6 border-2 border-white">Usługi Inżynieryjne</td>
                <td className="p-4 md:p-6 text-right border-2 border-white">$1.7M</td>
              </tr>
              <tr className="bg-black text-white border-2 border-white">
                <td className="p-4 md:p-6 border-2 border-white">Usługi Architektoniczne</td>
                <td className="p-4 md:p-6 text-right border-2 border-white">$1.8M</td>
              </tr>
              <tr className="bg-black text-white border-2 border-white">
                <td className="p-4 md:p-6 border-2 border-white">Planowanie Projektu</td>
                <td className="p-4 md:p-6 text-right border-2 border-white">$1.2M</td>
              </tr>
              <tr className="bg-black text-white border-2 border-white font-bold">
                <td className="p-4 md:p-6 border-2 border-white">Łącznie</td>
                <td className="p-4 md:p-6 text-right border-2 border-white">$4.7M</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </motion.div>
  );
}
