import React, { useEffect } from "react";
import { HashRouter as Router } from "react-router-dom"; // HashRouter pozwala nawigować poprawnie
import Header from "./components/Header";
import { HeroSection } from "./components/HeroSection";
import PieChartPage from "./components/PieChartPage";
import ResidentialProjects from "./components/ResidentialProjects";
import CommercialDevelopment from "./components/CommercialDevelopment";
import WhatItCouldMean from "./components/WhatItCouldMean";
import Roadmap from "./components/Roadmap";
import CostEstimate from "./components/CostEstimate";
import ContactPage from "./components/ContactPage";

function App() {
  // Funkcja do przewijania do sekcji po kliknięciu linku
  const handleHashChange = () => {
    const { hash } = window.location;
    if (hash) {
      const target = document.querySelector(hash);
      if (target) {
        setTimeout(() => {
          target.scrollIntoView({ behavior: "smooth", block: "start" });
        }, 100); // Małe opóźnienie, aby uniknąć problemu z ładowaniem
      }
    }
  };

  // Nasłuchiwanie zmian w hash (np. #contact, #roadmap)
  useEffect(() => {
    handleHashChange(); // Przewija po załadowaniu strony
    window.addEventListener("hashchange", handleHashChange);
    return () => {
      window.removeEventListener("hashchange", handleHashChange);
    };
  }, []);

  return (
    <Router>
      <div className="font-sans bg-gray-50">
        <Header />
        <main>
          <HeroSection />
          <PieChartPage />
          <ResidentialProjects />
          <CommercialDevelopment />
          <WhatItCouldMean />
          <Roadmap />
          <CostEstimate />
          <ContactPage />
        </main>
      </div>
    </Router>
  );
}

export default App;

