import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { Line } from "react-chartjs-2";
import { Chart as ChartJS, LineElement, PointElement, LinearScale, Title, Tooltip, Legend, CategoryScale } from "chart.js";

ChartJS.register(LineElement, PointElement, LinearScale, Title, Tooltip, Legend, CategoryScale);

export default function Roadmap() {
  const [labels, setLabels] = useState([
    "2025 - 2026",
    "2026 - 2027",
    "2027 - 2028",
    "2029 - 2030",
    "2030"
  ]);

  const actions = [
    "Rozpoczęcie projektu",
    "Planowanie i rozwój",
    "Budowa i infrastruktura",
    "Testowanie i optymalizacja",
    "Wdrożenie i ekspansja"
  ];

  const [data, setData] = useState({
    labels: labels,
    datasets: [
      {
        label: "Plan Działania",
        data: [1, 2, 1, 2, 1],
        borderColor: "#6C6C6C",
        backgroundColor: "#6C6C6C",
        pointBackgroundColor: "#4A4A4A",
        pointBorderColor: "#ffffff",
        pointRadius: 8,
        pointHoverRadius: 10,
        fill: false,
        tension: 0.3,
      },
    ],
  });

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    scales: {
      x: {
        grid: {
          display: false,
        },
        ticks: {
          font: {
            size: 10,
            weight: "bold",
          },
          color: "#333",
          maxRotation: 30,
          minRotation: 0,
          autoSkip: false,
        },
      },
      y: {
        display: false,
      },
    },
    plugins: {
      legend: {
        display: false,
      },
      tooltip: {
        callbacks: {
          label: function (tooltipItem) {
            return actions[tooltipItem.dataIndex];
          },
        },
      },
    },
  };

  return (
    <motion.div 
      id="roadmap"
      className="w-full min-h-[60vh] flex flex-col items-center justify-center bg-white px-4 md:px-6 py-6 md:py-10"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 1 }}
    >
      <h1 className="text-xl md:text-3xl font-bold text-gray-700 mb-6 md:mb-10 text-center">Plan Działania</h1>
      <div className="relative w-full max-w-6xl h-56 md:h-72 bg-gray-100 rounded-3xl flex flex-col items-center p-4 md:p-8 shadow-lg">
        <Line data={data} options={options} />
      </div>
      <div className="grid grid-cols-1 md:grid-cols-5 gap-3 mt-4 md:mt-6 w-full max-w-6xl text-center">
        {labels.map((label, index) => (
          <div key={index} className="flex flex-col items-center text-sm md:text-base">
            <p className="font-bold text-gray-800">{label}</p>
            <p className="text-gray-600">{actions[index]}</p>
          </div>
        ))}
      </div>
    </motion.div>
  );
}